wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7059352664718801)
,p_plug_name=>'BAS'
,p_static_id=>'bas'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div id="scanContainer" style="text-align:center; padding:20px;">',
'  ',
unistr('  <h2>\D83D\DCF8 Face Scanning System</h2>'),
'    <div style="margin:20px 0;">',
'    <video id="videoFeed" width="640" height="480" ',
'           style="border:2px solid #007bff; border-radius:10px;"',
'           autoplay muted></video>',
'  </div>',
'  ',
'  <!-- Canvas (Hidden) -->',
'  <canvas id="canvasOverlay" width="640" height="480" style="display:none;"></canvas>',
'  ',
'  <!-- Buttons -->',
'  <div style="margin:20px 0;">',
'    <button id="btnStartScan" class="btn btn-primary" style="padding:10px 30px; font-size:16px; margin:5px;">',
unistr('      \25B6\FE0F Start Scanning'),
'    </button>',
'    <button id="btnStopScan" class="btn btn-danger" style="padding:10px 30px; font-size:16px; margin:5px;" disabled>',
unistr('      \23F9\FE0F Stop Scanning'),
'    </button>',
'    <button id="btnCapture" class="btn btn-success" style="padding:10px 30px; font-size:16px; margin:5px;" disabled>',
unistr('      \D83D\DCF7 Capture Face'),
'    </button>',
'  </div>',
'  ',
'  <!-- Result Display -->',
'  <div id="scanResult" style="margin:20px 0; font-size:16px;">',
'    <p style="color:#666;">Status: Ready to scan</p>',
'  </div>',
'  ',
'  <!-- Details -->',
'  <div id="employeeDetails" style="display:none; margin:20px 0; padding:20px; ',
'                                   background:#f0f0f0; border-radius:10px;">',
'    <h3 id="detailName">-</h3>',
'    <p><strong>Employee ID:</strong> <span id="detailID">-</span></p>',
'    <p><strong>Department:</strong> <span id="detailDept">-</span></p>',
'    <p><strong>Position:</strong> <span id="detailPos">-</span></p>',
'    <p><strong>Match Score:</strong> <span id="detailScore">-</span>%</p>',
'    <p><strong>Status:</strong> <span id="detailStatus">-</span></p>',
'  </div>',
'  ',
'</div>',
'',
'<!-- Load face-api library -->',
'<script src="https://cdnjs.cloudflare.com/ajax/libs/axios/1.6.5/axios.min.js"></script>',
'<script src="https://cdn.jsdelivr.net/npm/@vladmandic/face-api@1.7.15/dist/face-api.min.js"></script>',
'',
'<style>',
'  #videoFeed {',
'    max-width: 100%;',
'    height: auto;',
'  }',
'  ',
'  .btn {',
'    border: none;',
'    padding: 10px 20px;',
'    border-radius: 5px;',
'    cursor: pointer;',
'    font-weight: bold;',
'  }',
'  ',
'  .btn-primary {',
'    background-color: #007bff;',
'    color: white;',
'  }',
'  ',
'  .btn-primary:hover {',
'    background-color: #0056b3;',
'  }',
'  ',
'  .btn-danger {',
'    background-color: #dc3545;',
'    color: white;',
'  }',
'  ',
'  .btn-danger:hover {',
'    background-color: #c82333;',
'  }',
'  ',
'  .btn-success {',
'    background-color: #28a745;',
'    color: white;',
'  }',
'  ',
'  .btn-success:hover {',
'    background-color: #218838;',
'  }',
'  ',
'  .btn:disabled {',
'    opacity: 0.5;',
'    cursor: not-allowed;',
'  }',
'</style>',
'',
'<script>',
'// ========================================',
'// FACE SCANNING SYSTEM - JavaScript',
'// ========================================',
'',
'let videoStream = null;',
'let isScanning = false;',
'let modelsLoaded = false;',
'',
'// Initialize on page load',
'document.addEventListener(''DOMContentLoaded'', async function() {',
'  console.log(''Page loaded, preparing face detection...'');',
'  await loadFaceModels();',
'});',
'',
'// Load face-api models',
'async function loadFaceModels() {',
'  try {',
'    console.log(''Loading face detection models...'');',
'    ',
'    const MODEL_URL = ''https://cdn.jsdelivr.net/npm/@vladmandic/face-api@1.7.15/model/'';',
'    ',
'    await Promise.all([',
'      faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL),',
'      faceapi.nets.faceLandmarkTinyNet.loadFromUri(MODEL_URL),',
'      faceapi.nets.faceRecognitionNet.loadFromUri(MODEL_URL),',
'      faceapi.nets.faceExpressionNet.loadFromUri(MODEL_URL)',
'    ]);',
'    ',
'    modelsLoaded = true;',
unistr('    updateStatus(''\2705 Face detection ready! Click "Start Scanning"'');'),
unistr('    console.log(''\2705 All models loaded successfully'');'),
'    ',
'  } catch (error) {',
'    console.error(''Error loading models:'', error);',
unistr('    updateStatus(''\274C Error loading models: '' + error.message);'),
'  }',
'}',
'',
'// Start Camera Stream',
'async function startScanning() {',
'  try {',
'    if (!modelsLoaded) {',
'      alert(''Face detection models still loading... Please wait'');',
'      return;',
'    }',
'    ',
'    console.log(''Starting camera...'');',
'    const video = document.getElementById(''videoFeed'');',
'    ',
'    videoStream = await navigator.mediaDevices.getUserMedia({',
'      video: {',
'        width: { ideal: 640 },',
'        height: { ideal: 480 },',
'        facingMode: ''user''',
'      },',
'      audio: false',
'    });',
'    ',
'    video.srcObject = videoStream;',
'    video.onloadedmetadata = () => {',
'      video.play();',
'    };',
'    ',
'    isScanning = true;',
unistr('    updateStatus(''\D83C\DFA5 Camera is ON - Face detection active'');'),
'    ',
'    // Enable/Disable buttons',
'    document.getElementById(''btnStartScan'').disabled = true;',
'    document.getElementById(''btnStopScan'').disabled = false;',
'    document.getElementById(''btnCapture'').disabled = false;',
'    ',
'    // Start continuous scanning',
'    scanningLoop();',
'    ',
'  } catch (error) {',
'    console.error(''Camera error:'', error);',
'    alert(''Camera access denied! Please allow camera permission.'');',
unistr('    updateStatus(''\274C Camera access denied'');'),
'  }',
'}',
'',
'// Stop Scanning',
'function stopScanning() {',
'  if (videoStream) {',
'    videoStream.getTracks().forEach(track => track.stop());',
'  }',
'  ',
'  const video = document.getElementById(''videoFeed'');',
'  video.srcObject = null;',
'  ',
'  isScanning = false;',
unistr('  updateStatus(''\23F9\FE0F Scanning stopped'');'),
'  ',
'  // Enable/Disable buttons',
'  document.getElementById(''btnStartScan'').disabled = false;',
'  document.getElementById(''btnStopScan'').disabled = true;',
'  document.getElementById(''btnCapture'').disabled = true;',
'  ',
'  document.getElementById(''employeeDetails'').style.display = ''none'';',
'}',
'',
'// Continuous Scanning Loop',
'async function scanningLoop() {',
'  if (!isScanning) return;',
'  ',
'  const video = document.getElementById(''videoFeed'');',
'  const canvas = document.getElementById(''canvasOverlay'');',
'  ',
'  try {',
'    const detections = await faceapi.detectAllFaces(video)',
'      .withFaceLandmarks()',
'      .withFaceDescriptors();',
'    ',
'    if (detections.length > 0) {',
'      const detection = detections[0];',
'      const descriptor = detection.descriptor;',
'      ',
'      // Show detected face info',
unistr('      updateStatus(`\2705 Face detected! Confidence: ${(detection.detection.score * 100).toFixed(1)}%`);'),
'      ',
'      // Store descriptor for capture',
'      document.getElementById(''videoFeed'').dataset.lastDescriptor = JSON.stringify(Array.from(descriptor));',
'      ',
'    } else {',
unistr('      updateStatus(''\D83D\DD0D Scanning... No face detected yet'');'),
'    }',
'    ',
'  } catch (error) {',
'    console.error(''Scanning error:'', error);',
'  }',
'  ',
'  // Continue loop',
'  requestAnimationFrame(scanningLoop);',
'}',
'',
'// Capture Face and Send to Backend',
'async function captureFace() {',
'  const video = document.getElementById(''videoFeed'');',
'  const lastDescriptor = video.dataset.lastDescriptor;',
'  ',
'  if (!lastDescriptor) {',
'    alert(''No face detected! Please position your face in the camera.'');',
'    return;',
'  }',
'  ',
'  try {',
unistr('    updateStatus(''\D83D\DCE4 Sending face data to server...'');'),
'    ',
'    const faceEmbedding = JSON.parse(lastDescriptor);',
'    ',
'    // Call our Express backend',
'    const response = await axios.post(''http://localhost:3000/api/ords/apex/hr/attendance/scan'', {',
'      faceEmbedding: faceEmbedding,',
'      action: ''CLOCK_IN'',',
'      deviceInfo: ''APEX-BROWSER-KIOSK'',',
'      location: ''Office Main Entrance'',',
'      snapshotUrl: null',
'    });',
'    ',
'    console.log(''Server response:'', response.data);',
'    ',
'    if (response.data.matched) {',
'      // Success!',
'      displayEmployeeDetails(response.data);',
'      playSuccessSound();',
unistr('      updateStatus(`\2705 MATCH FOUND: ${response.data.employee.name} (${response.data.matchScore}%)`);'),
'      ',
'    } else {',
'      // No match',
unistr('      updateStatus(`\274C NO MATCH: Score ${response.data.matchScore}% (Need 72%)`);'),
'      document.getElementById(''employeeDetails'').style.display = ''none'';',
'    }',
'    ',
'  } catch (error) {',
'    console.error(''Error:'', error);',
unistr('    updateStatus(''\274C Server error: '' + (error.response?.data?.message || error.message));'),
'  }',
'}',
'',
'// Display Employee Details',
'function displayEmployeeDetails(data) {',
'  const emp = data.employee;',
'  ',
'  document.getElementById(''detailName'').textContent = emp.name;',
'  document.getElementById(''detailID'').textContent = emp.id;',
'  document.getElementById(''detailDept'').textContent = emp.department;',
'  document.getElementById(''detailPos'').textContent = emp.position;',
'  document.getElementById(''detailScore'').textContent = data.matchScore;',
'  document.getElementById(''detailStatus'').textContent = data.attendanceStatus;',
'  ',
'  document.getElementById(''employeeDetails'').style.display = ''block'';',
'}',
'',
'// Update Status Message',
'function updateStatus(message) {',
'  document.getElementById(''scanResult'').innerHTML = `<p style="font-size:16px;">${message}</p>`;',
'}',
'',
'// Play Success Sound (optional)',
'function playSuccessSound() {',
'  const audioContext = new (window.AudioContext || window.webkitAudioContext)();',
'  const oscillator = audioContext.createOscillator();',
'  const gainNode = audioContext.createGain();',
'  ',
'  oscillator.connect(gainNode);',
'  gainNode.connect(audioContext.destination);',
'  ',
'  oscillator.frequency.value = 800;',
'  oscillator.type = ''sine'';',
'  ',
'  gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);',
'  gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.5);',
'  ',
'  oscillator.start(audioContext.currentTime);',
'  oscillator.stop(audioContext.currentTime + 0.5);',
'}',
'',
'// Button Event Listeners',
'document.getElementById(''btnStartScan'').addEventListener(''click'', startScanning);',
'document.getElementById(''btnStopScan'').addEventListener(''click'', stopScanning);',
'document.getElementById(''btnCapture'').addEventListener(''click'', captureFace);',
'</script>',
''))
