'<!-- APEX Static Region - Face Scanner -->',
'<div id="face-scanner">',
'    <video id="video" autoplay playsinline></video>',
'    <canvas id="canvas" style="display:none"></canvas>',
'    <div id="result"></div>',
'    <button onclick="startScan()">Start Face Scan</button>',
'</div>',
'',
'<script>',
'// Load face-api.js',
'async function loadModels() {',
'    await faceapi.nets.ssdMobilenetv1.loadFromUri(''/models'');',
'    await faceapi.nets.faceLandmark68Net.loadFromUri(''/models'');',
'    await faceapi.nets.faceRecognitionNet.loadFromUri(''/models'');',
'}',
'',
'async function startScan() {',
'    const video = document.getElementById(''video'');',
'    const stream = await navigator.mediaDevices.getUserMedia({ video: {} });',
'    video.srcObject = stream;',
'    ',
'    // Detect face',
'    const detections = await faceapi.detectSingleFace(video)',
'        .withFaceLandmarks()',
'        .withFaceDescriptor();',
'    ',
'    if (detections) {',
'        const embedding = Array.from(detections.descriptor);',
'        ',
'        // Call Oracle ORDS REST API',
'        const response = await fetch(''/ords/apex_hr/attendance/scan'', {',
'            method: ''POST'',',
'            headers: { ''Content-Type'': ''application/json'' },',
'            body: JSON.stringify({ ',
'                face_embedding: embedding,',
'                action: ''CLOCK_IN'',',
'                device_info: ''APEX Web Scanner'',',
'                location: ''Main Entrance''',
'            })',
'        });',
'        ',
'        const result = await response.json();',
'        document.getElementById(''result'').innerHTML = ',
'            result.matched === ''TRUE'' ',
unistr('                ? `\2705 Welcome ${result.name}! (${result.score}% match)`'),
unistr('                : ''\274C Face not recognized (72% threshold required)'';'),
'    }',
'}',
'</script>'))
