wwv_flow_imp_page.create_page(
 p_id=>4
,p_name=>'LED Control'
,p_alias=>'LED-CONTROL'
,p_step_title=>'Machine Mentinance'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// \2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550'),
'// Flask API URL - APNA IP DALO',
unistr('// \2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550\2550'),
'var FLASK_URL = ''http://172.16.17.10:5000'';',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Page Load: Devices Load karo',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'$(document).ready(function() {',
'    loadDevices();',
'    checkStatus();',
'    setInterval(checkStatus, 30000);',
'});',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Devices Dropdown Load karo Flask se',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function loadDevices() {',
'    fetch(FLASK_URL + ''/api/devices'')',
'    .then(function(r) { return r.json(); })',
'    .then(function(data) {',
'        var select = document.getElementById(''device_ip'');',
'',
'        if (data.success && data.devices.length > 0) {',
'            data.devices.forEach(function(device) {',
'                var option = document.createElement(''option'');',
'                option.value = device.ip;',
'                option.text  = device.ip +',
'                               '' - '' + (device.type || ''LED Device'');',
'                select.appendChild(option);',
'            });',
'        } else {',
'            // Flask se nahi mila',
'            // Oracle DB se load karo',
'            loadDevicesFromDB();',
'        }',
'    })',
'    .catch(function() {',
'        loadDevicesFromDB();',
'    });',
'}',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Oracle DB se Devices Load karo',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function loadDevicesFromDB() {',
'    apex.server.process(''GET_DEVICES'', {}, {',
'        success: function(data) {',
'            var select = document.getElementById(''device_ip'');',
'            if (data.devices) {',
'                data.devices.forEach(function(d) {',
'                    var option    = document.createElement(''option'');',
'                    option.value  = d.ip;',
'                    option.text   = d.ip + '' - '' + d.name;',
'                    select.appendChild(option);',
'                });',
'            }',
'        }',
'    });',
'}',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Color Change - Main Function',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function changeColor() {',
'    var ip    = document.getElementById(''device_ip'').value;',
'    var color = document.getElementById(''led_color'').value;',
'',
'    // Validation',
'    if (!ip) {',
unistr('        showResult(''\274C Device select karo!'', ''error'');'),
'        return;',
'    }',
'    if (!color) {',
unistr('        showResult(''\274C Color select karo!'', ''error'');'),
'        return;',
'    }',
'',
'    // Loading',
unistr('    showResult(''\23F3 Sending...'', ''info'');'),
'',
'    // Flask API Call',
'    fetch(FLASK_URL + ''/api/led/color'', {',
'        method : ''POST'',',
'        headers: { ''Content-Type'': ''application/json'' },',
'        body   : JSON.stringify({',
'            ip   : ip,',
'            color: color',
'        })',
'    })',
'    .then(function(r) { return r.json(); })',
'    .then(function(data) {',
'        if (data.success) {',
'            showResult(',
unistr('                ''\2705 Device '' + ip +'),
unistr('                '' \2192 '' + color.toUpperCase() + '' Done!'','),
'                ''success''',
'            );',
'',
'            // DB Update',
'            updateDB(ip, color);',
'',
'            // Report Refresh',
'            setTimeout(function() {',
'                apex.region(''device_report'').refresh();',
'            }, 500);',
'',
'        } else {',
unistr('            showResult(''\274C Error: '' + data.error, ''error'');'),
'        }',
'    })',
'    .catch(function(err) {',
unistr('        showResult(''\274C Flask Error: '' + err.message, ''error'');'),
'    });',
'}',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// DB Update',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function updateDB(ip, color) {',
'    apex.server.process(''UPDATE_LED_COLOR'', {',
'        x01: ip,',
'        x02: color',
'    }, {',
'        success: function() {',
'            console.log(''DB Updated!'');',
'        }',
'    });',
'}',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Result Message Show',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function showResult(msg, type) {',
'    var el = document.getElementById(''result_msg'');',
'    el.style.display = ''block'';',
'    el.innerHTML     = msg;',
'',
'    var colors = {',
'        success: { bg: ''#d4edda'', color: ''#155724'', border: ''#c3e6cb'' },',
'        error  : { bg: ''#f8d7da'', color: ''#721c24'', border: ''#f5c6cb'' },',
'        info   : { bg: ''#d1ecf1'', color: ''#0c5460'', border: ''#bee5eb'' }',
'    };',
'',
'    var c = colors[type] || colors.info;',
'    el.style.background   = c.bg;',
'    el.style.color        = c.color;',
'    el.style.border       = ''1px solid '' + c.border;',
'}',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Status Check',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function checkStatus() {',
'    fetch(FLASK_URL + ''/api/status'')',
'    .then(function(r) { return r.json(); })',
'    .then(function(data) {',
'        var el = document.getElementById(''bridge_status'');',
'        if (!el) return;',
'',
'        if (data.mqtt === ''connected'') {',
unistr('            el.innerHTML = ''\D83D\DFE2 InLine 7.0 | '' + ''Devices: '' + data.total_devices; /// Flask + MQTT Online'),
'            el.style.color = ''green'';',
'        } else {',
unistr('            el.innerHTML   = ''\D83D\DD34 MQTT Disconnected!'';'),
'            el.style.color = ''red'';',
'        }',
'    })',
'    .catch(function() {',
'        var el = document.getElementById(''bridge_status'');',
'        if (el) {',
unistr('            el.innerHTML   = ''\D83D\DD34 Flask Offline!'';'),
'            el.style.color = ''red'';',
'        }',
'    });',
'}'))
