 p_id=>wwv_flow_imp.id(6458360503263014)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'UPDATE_LED_COLOR'
,p_static_id=>'update-led-color'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'DECLARE',
'    v_ip    VARCHAR2(20) := APEX_APPLICATION.G_X01;',
'    v_color VARCHAR2(20) := APEX_APPLICATION.G_X02;',
'    v_old   VARCHAR2(20);',
'BEGIN',
'    SELECT current_color',
'    INTO   v_old',
'    FROM   led_devices',
'    WHERE  ip_address = v_ip;',
'',
'    UPDATE led_devices',
'    SET    current_color = v_color,',
'           last_seen     = SYSTIMESTAMP,',
'           status        = ''online''',
'    WHERE  ip_address = v_ip;',
'',
'    INSERT INTO led_color_log (',
'        ip_address, old_color,',
'        new_color,  changed_by',
'    ) VALUES (',
'        v_ip,   v_old,',
'        v_color, NVL(APEX_APPLICATION.G_USER, ''SYSTEM'')',
'    );',
'',
'    COMMIT;',
'',
'    APEX_JSON.open_object;',
'    APEX_JSON.write(''status'', ''success'');',
'    APEX_JSON.close_object;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        APEX_JSON.open_object;',
'        APEX_JSON.write(''status'', ''error'');',
'        APEX_JSON.write(''message'', SQLERRM);',
'        APEX_JSON.close_object;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>6458360503263014
,p_created_on=>wwv_flow_imp.dz('20260806100447Z')
,p_updated_on=>wwv_flow_imp.dz('20260806100447Z')
,p_created_by=>'AMIR'
,p_updated_by=>'AMIR'
);
end;
