wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11434444262338107)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PROCESS_UPLOAD_PHOTO'
,p_static_id=>'process-upload-photo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_photo_id  NUMBER;',
'    v_blob_data BLOB;',
'    v_filename  VARCHAR2(256);',
'BEGIN',
'',
'    -- Check whether photo is selected',
'    IF :P5_PHOTO IS NULL THEN',
'',
'        apex_error.add_error(',
unistr('            p_message          => ''\0628\0631\0627\06C1 \06A9\0631\0645 \06A9\0648\0626\06CC \0641\0648\0679\0648 \0645\0646\062A\062E\0628 \06A9\0631\06CC\06BA'','),
'            p_display_location => ''inline''',
'        );',
'',
'        RETURN;',
'',
'    END IF;',
'',
'',
'    -- Get uploaded file from APEX temporary files',
'    SELECT blob_content,',
'           filename',
'      INTO v_blob_data,',
'           v_filename',
'      FROM apex_application_temp_files',
'     WHERE name = :P5_PHOTO;',
'',
'',
'    -- Save original photo',
'    SP_SAVE_ORIGINAL_PHOTO(',
'        p_blob_file   => v_blob_data,',
'        p_filename    => v_filename,',
'        p_folder_path => ''C:\PICTURE'',',
'        p_photo_id    => v_photo_id',
'    );',
'',
'',
'    -- Success message',
'    apex_application.g_print_success_message :=',
'        ''Photo successfully uploaded. Photo ID = '' || v_photo_id;',
'',
'',
'EXCEPTION',
'',
'    WHEN NO_DATA_FOUND THEN',
'',
'        apex_error.add_error(',
unistr('            p_message          => ''Uploaded file \0646\06C1\06CC\06BA \0645\0644\0627\06D4 \0628\0631\0627\06C1 \06A9\0631\0645 \062F\0648\0628\0627\0631\06C1 photo select \06A9\0631\06CC\06BA\06D4'','),
'            p_display_location => ''inline''',
'        );',
'',
'    WHEN OTHERS THEN',
'',
'        apex_error.add_error(',
unistr('            p_message          => ''Upload \0645\06CC\06BA \062E\0631\0627\0628\06CC: '' || SQLERRM,'),
'            p_display_location => ''inline''',
'        );',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(11434565988338108)
,p_internal_uid=>11434444262338107
,p_created_on=>wwv_flow_imp.dz('20260811165312Z')
,p_updated_on=>wwv_flow_imp.dz('20260811181255Z')
,p_created_by=>'AMIR'
,p_updated_by=>'AMIR'
);
end;
/
