wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(22771411405579021)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SP_SAVE_ORIGINAL_PHOTO'
,p_static_id=>'sp-save-original-photo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    v_blob_data      BLOB;',
'    v_original_name  VARCHAR2(500);',
'',
'    v_folder_path    VARCHAR2(1000);',
'    v_new_filename   VARCHAR2(500);',
'    v_full_path      VARCHAR2(1500);',
'',
'    v_ext            VARCHAR2(50);',
'    v_count          NUMBER;',
'',
'BEGIN',
'',
'    ------------------------------------------------------------------',
'    -- HEADER ID',
'    ------------------------------------------------------------------',
'',
'    IF :P9_HEADER_ID IS NULL THEN',
'',
'        apex_error.add_error(',
unistr('            p_message => ''Header ID \0645\0648\062C\0648\062F \0646\06C1\06CC\06BA \06C1\06D2\06D4'','),
'            p_display_location => ''inline''',
'        );',
'',
'        RETURN;',
'',
'    END IF;',
'',
'',
'    ------------------------------------------------------------------',
'    -- LINE ID',
'    ------------------------------------------------------------------',
'',
'    IF :P9_LINE_ID IS NULL THEN',
'',
'        apex_error.add_error(',
unistr('            p_message => ''Line ID \0645\0648\062C\0648\062F \0646\06C1\06CC\06BA \06C1\06D2\06D4'','),
'            p_display_location => ''inline''',
'        );',
'',
'        RETURN;',
'',
'    END IF;',
'',
'',
'    ------------------------------------------------------------------',
'    -- FILE',
'    ------------------------------------------------------------------',
'',
'    IF :P9_FILE IS NULL THEN',
'',
'        apex_error.add_error(',
unistr('            p_message => ''\0628\0631\0627\06C1 \06A9\0631\0645 \062A\0635\0648\06CC\0631 \0645\0646\062A\062E\0628 \06A9\0631\06CC\06BA\06D4'','),
'            p_display_location => ''inline''',
'        );',
'',
'        RETURN;',
'',
'    END IF;',
'',
'',
'    ------------------------------------------------------------------',
'    -- GET TEMP FILE',
'    ------------------------------------------------------------------',
'',
'    SELECT blob_content,',
'           filename',
'      INTO v_blob_data,',
'           v_original_name',
'      FROM apex_application_temp_files',
'     WHERE name = :P9_FILE;',
'',
'',
'    ------------------------------------------------------------------',
'    -- GET EXTENSION',
'    ------------------------------------------------------------------',
'',
'    IF INSTR(v_original_name, ''.'', -1) > 0 THEN',
'',
'        v_ext :=',
'            LOWER(',
'                SUBSTR(',
'                    v_original_name,',
'                    INSTR(v_original_name, ''.'', -1) + 1',
'                )',
'            );',
'',
'    ELSE',
'',
'        v_ext := ''jpg'';',
'',
'    END IF;',
'',
'',
'    ------------------------------------------------------------------',
'    -- HEADER FOLDER',
'    ------------------------------------------------------------------',
'',
'    v_folder_path :=',
'        ''C:\PICTURE\'' ||',
'        TO_CHAR(:P9_HEADER_ID);',
'',
'',
'    ------------------------------------------------------------------',
'    -- GET NEXT SEQUENCE FROM ACTUAL FOLDER',
'    --',
'    -- Example:',
'    --',
'    -- Existing:',
'    -- 4(1).png',
'    -- 4(2).png',
'    -- 4(3).png',
'    --',
'    -- Returns:',
'    -- 4',
'    ------------------------------------------------------------------',
'',
'    v_count :=',
'        SP_GET_PHOTO_SEQUENCE(',
'            p_folder_path => v_folder_path,',
'            p_line_id     => TO_CHAR(:P9_LINE_ID),',
'            p_extension   => v_ext',
'        );',
'',
'',
'    ------------------------------------------------------------------',
'    -- CREATE FILE NAME',
'    ------------------------------------------------------------------',
'',
'    v_new_filename :=',
'           TO_CHAR(:P9_LINE_ID)',
'        || ''(''',
'        || TO_CHAR(v_count)',
'        || '').''',
'        || v_ext;',
'',
'',
'    ------------------------------------------------------------------',
'    -- SAVE PHOTO',
'    ------------------------------------------------------------------',
'',
'    v_full_path :=',
'        SP_SAVE_PHOTO_EXACT(',
'            p_blob_file   => v_blob_data,',
'            p_folder_path => v_folder_path,',
'            p_filename    => v_new_filename',
'        );',
'',
'',
'    ------------------------------------------------------------------',
'    -- SUCCESS',
'    ------------------------------------------------------------------',
'',
'    apex_application.g_print_success_message :=',
'          ''Photo successfully uploaded.''',
'       || ''<br>Folder: ''',
'       || v_folder_path',
'       || ''<br>File: ''',
'       || v_new_filename;',
'',
'',
'EXCEPTION',
'',
'    WHEN NO_DATA_FOUND THEN',
'',
'        apex_error.add_error(',
'            p_message =>',
unistr('                ''Uploaded file \0646\06C1\06CC\06BA \0645\0644\0627\06D4'','),
'            p_display_location => ''inline''',
'        );',
'',
'    WHEN OTHERS THEN',
'',
